    12	// isTerminal reports whether w is an interactive terminal. It is dependency-free
    13	// (no golang.org/x/term): a character device is a TTY, a pipe/file/bytes.Buffer
    14	// is not. Used to decide whether to draw a live progress bar and whether to
    15	// render a human summary instead of JSON.
    16	func isTerminal(w io.Writer) bool {
    17		f, ok := w.(*os.File)
    18		if !ok {
    19			return false
    20		}
    21		info, err := f.Stat()
    22		if err != nil {
    23			return false
    24		}
    25		return info.Mode()&os.ModeCharDevice != 0
    26	}
    27	
    28	// progressBar renders indexing progress as a single self-overwriting line on a
    29	// terminal. It is only wired up when the target is a TTY (see runIndex), so the
    30	// ANSI clear-to-end-of-line (\033[K) and carriage-return redraws are safe, and
    31	// stdout — which may carry JSON — is never touched.
    32	type progressBar struct {
    33		w        io.Writer
    34		label    string
    35		rendered bool
    36	}
    37	
    38	func newProgressBar(w io.Writer, label string) *progressBar {
    39		return &progressBar{w: w, label: label}
    40	}
    41	
    42	// update redraws the bar for one progress event. With a known file total it
    43	// shows a filled bar and a ratio; before the total is known (the "start" phase)
    44	// it shows a running count.
    45	func (b *progressBar) update(e sem.ProgressEvent) {
    46		elapsed := e.Elapsed.Round(100 * time.Millisecond)
    47		var line string
    48		if e.FilesTotal > 0 {
    49			const width = 24
    50			filled := e.FilesDone * width / e.FilesTotal
    51			if filled > width {
    52				filled = width
    53			}
    54			bar := repeat('█', filled) + repeat('░', width-filled)
    55			line = fmt.Sprintf("%s [%s] %d/%d files · %s symbols · %s relations · %s",
    56				b.label, bar, e.FilesDone, e.FilesTotal,
    57				humanInt(int64(e.Symbols)), humanInt(int64(e.Relations)), elapsed)
    58		} else {
    59			line = fmt.Sprintf("%s… %s symbols · %s relations · %s",
    60				b.label, humanInt(int64(e.Symbols)), humanInt(int64(e.Relations)), elapsed)
    61		}
    62		fmt.Fprintf(b.w, "\r%s\033[K", line)
    63		b.rendered = true
    64	}
    65	
    66	// clear erases the bar line so the following output starts clean. It is a no-op
    67	// when nothing was ever drawn (e.g. a cache hit that returns before any work).
    68	func (b *progressBar) clear() {
    69		if !b.rendered {
    70			return
    71		}
    72		fmt.Fprint(b.w, "\r\033[K")
    73	}
